export const VOD_CSS = "/*\n * The VOD's intro and outro, on the loop's stage: same backdrop, same palette,\n * same typefaces — the video opens on what the room saw between two talks.\n * No bottom band and no permanent logo here: the frame is the talk's only.\n */\n\n/* Nothing shows before the typefaces and images are in: a frame half-drawn in a\n   fallback face would be captured as is. */\nbody:not(.pret) #clip { visibility: hidden; }\n\n#noir { position: absolute; inset: 0; z-index: 11; background: #000; opacity: 0; pointer-events: none; }\n\n.vod { position: absolute; inset: 0; z-index: 1; }\n\n/* ---------- Intro ---------- */\n.vod-intro {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: space-between;\n  padding: 84px 140px 96px;\n  text-align: center;\n}\n.vod-tete { display: flex; flex-direction: column; align-items: center; gap: 22px; }\n.vod-logo { width: 760px; height: 170px; object-fit: contain; }\n.vod-logo[hidden] { display: none; }\n.vod-edition { font: 800 42px var(--f-texte); color: var(--orange); letter-spacing: .02em; }\n\n.vod-talk { width: 100%; display: flex; flex-direction: column; align-items: center; gap: 26px; }\n.vod-categorie {\n  padding: 8px 28px 10px;\n  border-radius: 999px;\n  background: var(--c, var(--cyan));\n  color: #fff;\n  font: 800 32px var(--f-texte);\n  box-shadow: 0 6px 0 rgba(27, 15, 85, .35);\n}\n.vod-categorie[hidden] { display: none; }\n.vod-titre {\n  width: 100%;\n  max-height: 330px;\n  font-size: 110px;\n  line-height: 1.05;\n  overflow-wrap: break-word;\n  --contour-epaisseur: .16em;\n}\n\n.vod-orateurs {\n  --photo: calc(220px - (var(--n, 1) - 1) * 18px);\n  list-style: none;\n  display: flex;\n  justify-content: center;\n  gap: calc(96px - (var(--n, 1) - 1) * 10px);\n}\n.vod-orateur { display: flex; flex-direction: column; align-items: center; gap: 12px; max-width: calc(var(--photo) + 180px); }\n.vod-photo {\n  width: var(--photo);\n  height: var(--photo);\n  display: grid;\n  place-items: center;\n  overflow: hidden;\n  border-radius: 50%;\n  border: 8px solid #fff;\n  background: #fff;\n  box-shadow: 0 0 0 8px var(--magenta), 0 18px 40px rgba(17, 12, 70, .45);\n  font: 800 calc(var(--photo) * .34) var(--f-titre);\n  color: #fff;\n}\n.vod-photo img { width: 100%; height: 100%; object-fit: cover; }\n.vod-nom { margin-top: 10px; font: 800 40px / 1.1 var(--f-texte); }\n.vod-societe { font: 700 30px / 1.2 var(--f-texte); color: #c6f3f7; }\n\n/* ---------- Outro ---------- */\n.vod-outro { display: flex; flex-direction: column; align-items: center; padding: 70px var(--marge) 60px; }\n.vod-merci { font-size: 120px; line-height: 1; text-align: center; white-space: pre-line; }\n.vod-outro.sans-sponsors { justify-content: center; }\n.vod-outro.sans-sponsors .vod-merci { font-size: 170px; }\n.vod-outro .sp-zone { width: 100%; margin-top: 24px; }\n.vod-outro .sp-rangs { gap: calc(44px * var(--k, 1)); }\n.vod-groupe { display: flex; flex-direction: column; align-items: center; gap: calc(22px * var(--k, 1)); }\n.vod-niveau { font-size: calc(46px * var(--k, 1)); line-height: 1; color: var(--orange); }\n.vod-autres {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: center;\n  align-items: flex-start;\n  gap: calc(40px * var(--k, 1)) calc(110px * var(--k, 1));\n}"
